00091 bool SDInterface::begin() {
00092   static bool _first_try = true;
00093   if (!ready() && (_first_try || (millis() - _last_try > 5000))) {
00094     _first_try = false;
00095     _last_try = millis();
00096     if (SD.begin(SD_CS_PIN)) {
00097       bool zen_test = SD.exists(TEST_FILENAME);
00098       if (!zen_test) {
00099         auto new_file = SD.open(TEST_FILENAME, FILE_WRITE);
00100         if (new_file) {
00101           new_file.close();
00102         }
00103       }
00104       _status = SD.exists(TEST_FILENAME) ? e_sd_config_status_config_no_content : e_sd_config_status_not_ready;
00105     }
00106   }
00107   return ready();
00108 }
