00129 bool SDInterface::log_println(const char* log_name, const char* data) {
00130   if (!ready()) {
00131     return false;
00132   }
00133   if (!SD.exists(log_name)) {
00134     M5_LOGD("Unable to log to non-existent file \"%s\".", log_name);
00135     return false;
00136   }
00137   // open the setup file in append mode to add lines
00138   auto log_file = SD.open(log_name, FILE_APPEND);
00139   if (!log_file) {
00140     end();
00141     M5_LOGD("Unable to open log file \"%s\".", log_name);
00142     return false;
00143   }
00144 
00145   log_file.println(data);
00146 
00147 //  M5_LOGD("Logged '%s' to '%s'.", data, log_name);
00148 
00149   log_file.close();
00150   _last_write = millis();
00151   return true;
00152 }
