00154 SDInterface::SdStatus SDInterface::has_safezen_content(uint16_t device_id) {
00155   if (!ready()) {
00156     _status = e_sd_config_status_not_ready;
00157     return _status;
00158   }
00159 
00160   if (!SD.exists(SETUP_FILENAME)) {
00161     return _status = e_sd_config_status_no_config_file;
00162   }
00163 
00164   // open the setup file
00165   auto setup_file = SD.open(SETUP_FILENAME, FILE_READ);
00166   _last_read = millis();
00167 
00168   if (!setup_file) {
00169     return _status = e_sd_config_status_config_no_content;
00170   }
00171 
00172   _device_id = 0;
00173 
00174   while (setup_file.available()) {
00175     String line = setup_file.readStringUntil('\n');
00176     if (line.startsWith(SD_CONFIG_FIELD_DEVICE_ID)) {
00177       sscanf(line.c_str(), sd_config_device_id_f, &_device_id);
00178       break;
00179     }
00180   }
00181 
00182   // close the setup file
00183   setup_file.close();
00184 
00185   if (_device_id == 0) {
00186     _status = e_sd_config_status_config_no_content;
00187   } else if (device_id && _device_id != device_id) {
00188     _status = e_sd_config_status_config_different_id;
00189   } else {
00190     _status = e_sd_config_status_ok;
00191   }
00192   return _status;
00193 }
00194 
00195 bool SDInterface::read_safezen_file_to_settings(LocalStorage& settings) {
00196   M5_LOGD("read_safezen_file_to_settings");
00197   if (!ready()) {
00198     return false;
00199   }
00200 
00201   File safecast_txt = SD.open(SETUP_FILENAME, FILE_READ);
00202   if (!safecast_txt) {
00203     return false;
00204   }
00205   _last_read = millis();
00206 
00207   char version[CONFIG_VAL_MAX] = "";
00208 
00209   String first_line = safecast_txt.readStringUntil('\n');
00210   if (first_line.startsWith(SD_CONFIG_FIELD_VERSION)) {
00211     sscanf(first_line.c_str(), sd_config_version_f, version);
00212   } else {
00213     // No version line read, expect latest version
00214     strcpy(version, VERSION_NUMBER);
00215     // Reopen settings, because first line was (probably) some configuration
00216     safecast_txt.close();
00217     safecast_txt = SD.open(SETUP_FILENAME, FILE_READ);
00218     if (!safecast_txt) {
00219       return false;
00220     }
00221   }
00222 
00223   // Add earlier / non-compatible versions here too
00224   if (strcmp(version, VERSION_NUMBER) == 0) {
00225     return read_safezen_file_latest(settings, safecast_txt);
00226   }
00227 
00228   // try with latest, at this point it should at least get the id
00229   return read_safezen_file_latest(settings, safecast_txt);
00230 }
