00232 bool SDInterface::read_safezen_file_latest(LocalStorage& settings, File& file) {
00233   // Device settings
00234   char access_point_password[CONFIG_VAL_MAX] = "";
00235   uint32_t alert_threshold = 0;
00236   uint8_t cpm_usvh = false;
00237   uint8_t manual_logging = false;
00238   uint8_t enable_journal = true;
00239   uint8_t log_void = false;
00240   uint32_t screen_dim_timeout = 0;
00241   uint32_t screen_off_timeout = 0;
00242   uint8_t animated_screensaver = true;
00243 
00244   // Connection settings
00245   char wifi_ssid[CONFIG_VAL_MAX] = "";
00246   char wifi_password[CONFIG_VAL_MAX] = "";
00247   char api_key[CONFIG_VAL_MAX] = "";
00248 
00249   // Location settings
00250   double fixed_latitude = 0;
00251   double fixed_longitude = 0;
00252   float fixed_range = 0;
00253   uint16_t max_dop = 0;
00254 
00255   while (file.available()) {
00256     String line = file.readStringUntil('\n');
00257     if (line.length() == 0) {
00258       continue;
00259     }
00260     else if (line.startsWith(SD_CONFIG_FIELD_DEVICE_ID)) {
00261       if (sscanf(line.c_str(), sd_config_device_id_f, &_device_id)) {
00262         settings.set_device_id(_device_id, true);
00263         M5_LOGD("Loaded from SD: device_id=%d", _device_id);
00264       }
00265     }
00266     else if (line.startsWith(SD_CONFIG_FIELD_API_KEY)) {
00267       if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_API_KEY) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_api_key_f, api_key)) {
00268         settings.set_api_key(api_key, true);
00269         M5_LOGD("Loaded from SD: api_key=%s", api_key);
00270       } else {
00271         M5_LOGD("Unable to load api_key");
00272       }
00273     }
00274     else if (line.startsWith(SD_CONFIG_FIELD_ACCESS_POINT_PASSWORD)) {
00275       if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_ACCESS_POINT_PASSWORD) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_access_point_password_f, access_point_password)) {
00276         settings.set_ap_password(access_point_password, true);
00277         M5_LOGD("Loaded from SD: access_point_password=%s", access_point_password);
00278       } else {
00279         M5_LOGD("Unable to load access_point_password");
00280       }
00281     }
00282     else if (line.startsWith(SD_CONFIG_FIELD_WIFI_SSID)) {
00283       if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_WIFI_SSID) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_wifi_ssid_f, wifi_ssid)) {
00284         settings.set_wifi_ssid(wifi_ssid, true);
00285         M5_LOGD("Loaded from SD: wifi_ssid=%s", wifi_ssid);
00286       } else {
00287         M5_LOGD("Unable to load wifi_ssid");
00288       }
00289     }
00290     else if (line.startsWith(SD_CONFIG_FIELD_WIFI_PASSWORD)) {
00291       if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_WIFI_PASSWORD) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_wifi_password_f, wifi_password)) {
00292         settings.set_wifi_password(wifi_password, true);
00293         M5_LOGD("Loaded from SD: wifi_password=%s", wifi_password);
00294       } else {
00295         M5_LOGD("Unable to load wifi_password");
00296       }
00297     }
00298     else if (line.startsWith(SD_CONFIG_FIELD_ALARM_THRESHOLD)) {
00299       if (_device_id && sscanf(line.c_str(), sd_config_alert_threshold_f, &alert_threshold)) {
00300         settings.set_alert_threshold(alert_threshold, true);
00301         M5_LOGD("Loaded from SD: alert_threshold=%d", alert_threshold);
00302       }
00303     }
00304     else if (line.startsWith(SD_CONFIG_FIELD_CPM_USVH)) {
00305       if (_device_id && sscanf(line.c_str(), sd_config_cpm_usvh_f, &cpm_usvh)) {
00306         settings.set_cpm_usvh(!!cpm_usvh, true);
00307         M5_LOGD("Loaded from SD: display_cpm=%d", !!cpm_usvh);
00308       }
00309     }
00310     else if (line.startsWith(SD_CONFIG_FIELD_MANUAL_LOGGING)) {
00311       if (_device_id && sscanf(line.c_str(), sd_config_manual_logging_f, &manual_logging)) {
00312         settings.set_manual_logging(!!manual_logging, true);
00313         M5_LOGD("Loaded from SD: manual_logging=%d", !!manual_logging);
00314       }
00315     }
00316     else if (line.startsWith(SD_CONFIG_FIELD_ENABLE_JOURNAL)) {
00317       if (_device_id && sscanf(line.c_str(), sd_config_enable_journal_f, &enable_journal)) {
00318         settings.set_enable_journal(!!enable_journal, true);
00319         M5_LOGD("Loaded from SD: enable_journal=%d", !!enable_journal);
00320       }
00321     }
00322     else if (line.startsWith(SD_CONFIG_FIELD_LOG_VOID)) {
00323       if (_device_id && sscanf(line.c_str(), sd_config_log_void_f, &log_void)) {
00324         settings.set_log_void(!!log_void, true);
00325         M5_LOGD("Loaded from SD: log_void=%d", !!log_void);
00326       }
00327     }
00328     else if (line.startsWith(SD_CONFIG_FIELD_SCREEN_DIM_TIMEOUT)) {
00329       if (_device_id && sscanf(line.c_str(), sd_config_screen_dim_timeout_f, &screen_dim_timeout)) {
00330         settings.set_screen_dim_timeout(screen_dim_timeout, true);
00331         M5_LOGD("Loaded from SD: manual_logging=%d", !!manual_logging);
00332       }
00333     }
00334     else if (line.startsWith(SD_CONFIG_FIELD_SCREEN_OFF_TIMEOUT)) {
00335       if (_device_id && sscanf(line.c_str(), sd_config_screen_off_timeout_f, &screen_off_timeout)) {
00336         settings.set_screen_off_timeout(screen_off_timeout, true);
00337         M5_LOGD("Loaded from SD: manual_logging=%d", !!manual_logging);
00338       }
00339     }
00340     else if (line.startsWith(SD_CONFIG_FIELD_ANIMATED_SCREENSAVER)) {
00341       if (_device_id && sscanf(line.c_str(), sd_config_animated_screensaver_f, &animated_screensaver)) {
00342         settings.set_animated_screensaver(!!animated_screensaver, true);
00343         M5_LOGD("Loaded from SD: manual_logging=%d", !!manual_logging);
00344       }
00345     }
00346     else if (line.startsWith(SD_CONFIG_FIELD_FIXED_LATITUDE)) {
00347       if (_device_id && sscanf(line.c_str(), sd_config_fixed_latitude_f, &fixed_latitude)) {
00348         settings.set_fixed_latitude(fixed_latitude, true);
00349         M5_LOGD("Loaded from SD: fixed_latitude=%0.6f", fixed_latitude);
00350       }
00351     }
00352     else if (line.startsWith(SD_CONFIG_FIELD_FIXED_LONGITUDE)) {
00353       if (_device_id && sscanf(line.c_str(), sd_config_fixed_longitude_f, &fixed_longitude)) {
00354         settings.set_fixed_longitude(fixed_longitude, true);
00355         M5_LOGD("Loaded from SD: fixed_longitude=%0.6f", fixed_longitude);
00356       }
00357     }
00358     else if (line.startsWith(SD_CONFIG_FIELD_FIXED_RANGE)) {
00359       if (_device_id && sscanf(line.c_str(), sd_config_fixed_range_f, &fixed_range)) {
00360         settings.set_fixed_range(fixed_range, true);
00361         M5_LOGD("Loaded from SD: fixed_range=%0.1f", fixed_longitude);
00362       }
00363     }
00364     else if (line.startsWith(SD_CONFIG_FIELD_DOP_MAX)) {
00365       if (_device_id && sscanf(line.c_str(), sd_config_dop_max_f, &max_dop)) {
00366         settings.set_dop_max(max_dop, true);
00367         M5_LOGD("Loaded from SD: max_dop=%u", max_dop);
00368       }
00369     } else {
00370       M5_LOGD("Skipped (currently) unsupported SAFEZEN line: %s ", line.c_str());
00371     }
00372   }
00373 
00374   file.close();
00375 
00376   _last_read = millis();
00377 
00378   if (_device_id == settings.get_device_id()) {
00379     M5_LOGD("Successfully loaded settings from SD config into memory");
00380     _status = e_sd_config_status_ok;
00381   } else {
00382     _status = e_sd_config_status_no_config_file;
00383   }
00384   return !!_device_id;
00385 }
