00472     _status = e_sd_config_status_ok;
00473     M5_LOGD("Finished writing SAFEZEN file:\n%s", written_safecast_txt.readString().c_str());
00474   }
00475 
00476   return true;
00477 }
00478 
00479 bool SDInterface::setup_log(const char* dir, const char* log_name_output, bool clear_on_exist) {
00480   if (SD.exists(log_name_output)) {
00481     if (clear_on_exist) {
00482       SD.remove(log_name_output);
00483     } else {
00484       return false;
00485     }
00486   } else {
00487     SD.mkdir(dir);
00488   }
00489   File safecast_txt = SD.open(log_name_output, FILE_WRITE);
00490   _last_write = millis();
00491   if (!safecast_txt) {
00492     end();
00493     return false;
00494   }
00495   safecast_txt.printf("");
00496   safecast_txt.close();
00497   return true;
00498 }
