00519 void SDInterface::delete_directory(const char* dirPath) {
00520   File dir = SD.open(dirPath);
00521   if (!dir) {
00522     M5_LOGD("Directory does not exist or could not be opened.");
00523     return;
00524   }
00525 
00526   if (!dir.isDirectory()) {
00527     M5_LOGD("The specified path is not a directory.");
00528     dir.close();
00529     return;
00530   }
00531 
00532   // Iterate through all files in the directory
00533   while (true) {
00534     File entry = dir.openNextFile();
00535     if (!entry) {
00536       // No more files in the directory
00537       break;
00538     }
00539 
00540     // Construct the full path
00541     String fullPath = String(dirPath) + "/" + entry.name();
00542 
00543     if (entry.isDirectory()) {
00544       // Recursively delete subdirectories
00545       M5_LOGD("Recursively deleting directory: %s", fullPath.c_str());
00546       delete_directory(fullPath.c_str());
00547 
00548       // Attempt to remove the directory itself after its contents are deleted
00549       if (!SD.rmdir(fullPath.c_str())) {
00550         M5_LOGD("Failed to remove directory: %s", fullPath.c_str());
00551       } else {
00552         M5_LOGD("Successfully removed directory: %s", fullPath.c_str());
00553       }
00554     } else {
00555       // Try to delete the file
00556       if (!SD.remove(fullPath.c_str())) {
00557         M5_LOGD("Failed to delete file: %s", fullPath.c_str());
00558       } else {
00559         M5_LOGD("Successfully deleted file: %s", fullPath.c_str());
00560       }
00561     }
00562     entry.close();
00563   }
00564 
00565   dir.close();
00566 
00567   // Finally, remove the empty directory itself
00568   if (SD.rmdir(dirPath)) {
00569     M5_LOGD("Directory deleted successfully: %s", dirPath);
00570   } else {
00571     M5_LOGD("Failed to delete the directory: %s", dirPath);
00572   }
00573 }
